from fastapi import APIRouter, FastAPI
from fastapi.exceptions import FastAPIError
import pytest

def test_include_router_into_itself():
    router = APIRouter()
    try:
        router.include_router(router)
    except FastAPIError as exc:
        assert str(exc) == "Cannot include a router into itself"
        print("Successfully raised FastAPIError")
    except Exception as exc:
        print(f"Raised unexpected exception: {type(exc).__name__}: {exc}")
    else:
        print("Did not raise any exception")

if __name__ == "__main__":
    test_include_router_into_itself()
